-- Wallet table schema
CREATE TABLE wallet_wallets (
    -- id: Wallet unique ID
    id VARCHAR(64) PRIMARY KEY,
    -- domain: Domain this wallet belongs to
    domain VARCHAR(64) NOT NULL,
    -- id_user: User ID who owns this wallet
    id_user VARCHAR(64) NOT NULL,
    -- name: Wallet display name
    name VARCHAR(255) NOT NULL,
    -- currency_code: Currency or points type code (e.g., 'USD', 'POINTS', 'CREDITS')
    currency_code VARCHAR(16) NOT NULL,
    -- balance: Current wallet balance (precision 1000)
    balance INTEGER NOT NULL,
    -- description: Optional wallet description
    description VARCHAR(200),
    -- is_active: Whether the wallet is active
    is_active INTEGER NOT NULL,
    -- metadata: Optional metadata for the wallet
    metadata VARCHAR(200),
    -- created: Wallet created date
    created DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- updated: Wallet updated date
    updated DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Index on domain: Domain this wallet belongs to
CREATE INDEX idx_wallet_wallets_domain ON wallet_wallets(domain);

-- Index on id_user: User ID who owns this wallet
CREATE INDEX idx_wallet_wallets_id_user ON wallet_wallets(id_user);

-- Index on currency_code: Currency or points type code (e.g., 'USD', 'POINTS', 'CREDITS')
CREATE INDEX idx_wallet_wallets_currency_code ON wallet_wallets(currency_code);

-- Index on is_active: Whether the wallet is active
CREATE INDEX idx_wallet_wallets_is_active ON wallet_wallets(is_active);

-- Index on created: Wallet created date
CREATE INDEX idx_wallet_wallets_created ON wallet_wallets(created);

-- Index on updated: Wallet updated date
CREATE INDEX idx_wallet_wallets_updated ON wallet_wallets(updated);


